insightsUI <- function(id) {
  ns<-NS(id)
  tagList(tags$p(class='eyebrow','REFLECT'),tags$h1('Is your time going where you intend?'),tags$p(class='lead','Estimates are a starting point. Your history helps make the next plan more realistic.'),
    checkboxInput(ns('deleted'),'Include deleted tasks and jobs in reports',TRUE),uiOutput(ns('metrics')),
    fluidRow(column(7,section('Estimated versus actual time',plotOutput(ns('comparison'),height='350px'),tags$p(class='hint','Each point is a completed task with a confirmed actual total. The diagonal means exactly on estimate. Unfinished tasks and older completions with unknown time are excluded.'))),column(5,section('What to try next',uiOutput(ns('recommendations'))))),
    fluidRow(column(7,section('Time over recent weeks',plotOutput(ns('trend'),height='240px'))),column(5,section('Progress with purpose',uiOutput(ns('goal_context'))))),section('Contract context',tableOutput(ns('contract')),tags$p(class='hint','Current salary and rates are contract references, not a reconstruction of past income. Recorded effort is actual time; value is not inferred from busyness.')),
    accordion('Opportunity follow-through',tableOutput(ns('opportunities')),tags$p(class='hint','Recorded preparation effort and your entered outcome stage. Finishing a preparation goal is distinct from winning funding or receiving money.')),
    section('Work by job',tableOutput(ns('jobs'))),section('Your task history',selectInput(ns('filter'),'Show',c('All tasks','Open tasks','Completed tasks','Deleted tasks')),tableOutput(ns('history')),downloadButton(ns('csv'),'Export task history CSV')),
    accordion('Correct or delete a time entry',selectInput(ns('log_id'),'Time entry',NULL),numericInput(ns('log_hours'),'Correct actual hours',1,min=.01,step=.25),dateInput(ns('log_date'),'Work date',Sys.Date()),textAreaInput(ns('log_note'),'Session note',rows=2),actionButton(ns('log_save'),'Save correction',class='btn-primary'),actionButton(ns('log_delete'),'Delete time entry',class='btn-danger-soft'),tags$p(class='hint','Corrections change reported actual time; they do not change your estimate of remaining work. Undo can restore a deleted entry. Entries for removed tasks can be corrected too.')),accordion('Delete a removed record from report history',selectInput(ns('purge_kind'),'Record type',c('Task'='tasks','Job and its history'='jobs','Goal'='goals','Opportunity'='opportunities')),selectInput(ns('purge_id'),'Removed record',NULL),actionButton(ns('purge'),'Remove from history',class='btn-danger-soft'),tags$p(class='hint','Unlike normal deletion, this removes the chosen historical record and associated time logs from the saved report data. Undo remains available in this session.')))
}
insightsServer <- function(id,state,commit)moduleServer(id,function(input,output,session){
  output$trend<-renderPlot({l<-all_records(state(),'logs');par(mar=c(4,4,1,1),bg=design_tokens$surface);if(!nrow(l)){plot.new();text(.5,.5,'Your recorded weeks will appear here.',col=design_tokens$muted);return()};w<-vapply(l$date,function(d)as.character(week_start(as.Date(d))),character(1));weeks<-sort(unique(w));weeks<-tail(weeks,8);h<-vapply(weeks,function(x)sum(l$hours[w==x]),numeric(1));barplot(h,names.arg=format(as.Date(weeks),'%d %b'),col=design_tokens$lavender,border=NA,ylab='Actual effort (hours)',cex.names=.8);box(bty='l',col=design_tokens$line)},res=110)
  output$goal_context<-renderUI({g<-goal_progress(state());if(!nrow(g))return(tags$p(class='empty-hint','Link tasks to a goal when that helps you make a more intentional choice.'));tagList(lapply(seq_len(min(4,nrow(g))),function(i)tags$div(class='mini-goal',tags$div(tags$strong(g$title[i]),tags$small(paste(g$progress[i],'/',g$target[i],g$unit[i]))),progress_bar(g$fraction[i]))))})
  output$contract<-renderTable({s<-state();l<-all_records(s,'logs');data.frame(Role=s$jobs$name,Model=s$jobs$pay_type,Weekly_salary=s$jobs$weekly_income,Rate=s$jobs$rate,Recorded_effort_h=vapply(s$jobs$id,function(id)sum(l$hours[l$job_id==id]),numeric(1)))},digits=2,striped=TRUE)
  output$opportunities<-renderTable({r<-opportunity_report(state());if(!nrow(r))return(NULL);r[,c('Opportunity','Role','Status','Logged_h','Remaining_h','Goal')]},digits=2,striped=TRUE)
  report<-reactive(task_report(state(),isTRUE(input$deleted)))
  output$metrics<-renderUI({m<-analytics_summary(report());fmt<-function(x,suffix='')if(is.na(x))'—'else paste0(round(x,2),suffix)
    tags$div(class='metric-grid',metric('Tasks in report',m$total,paste(m$complete,'complete ·',m$open,'open ·',m$deleted,'deleted')),metric('Actual time recorded',paste0(round(m$hours,2),' h'),'Partial and completed work'),metric('Median completed task',fmt(m$median,' h'),paste(m$verified,'verified completion totals')),metric('Median actual / estimate',fmt(m$ratio,'×'),'Completed, verified tasks only'))})
  output$comparison<-renderPlot({r<-report();r<-r[r$Verified,,drop=FALSE];par(mar=c(4,4,1,1),bg=design_tokens$surface);if(!nrow(r)){plot.new();text(.5,.5,'Finish a task and confirm its actual hours\nto see your first comparison.',col=design_tokens$muted);return()};lim<-max(1,r$Original_h,r$Actual_h)*1.1;plot(r$Original_h,r$Actual_h,xlim=c(0,lim),ylim=c(0,lim),pch=21,bg=ifelse(r$Actual_h>r$Original_h,design_tokens$clay,design_tokens$lavender),col=design_tokens$surface,cex=1.8,xlab='Original estimate (hours)',ylab='Actual time (hours)');abline(0,1,col=design_tokens$muted,lty=2);grid(col=design_tokens$line)},res=110)
  output$recommendations<-renderUI(tags$ul(class='recommendation-list',lapply(behaviour_recommendations(report()),tags$li)))
  output$jobs<-renderTable(job_report(report()),digits=2,striped=TRUE,na='Not enough data')
  filtered<-reactive({r<-report();switch(input$filter %||% 'All tasks','Open tasks'=r[!r$Complete&!r$Deleted,,drop=FALSE],'Completed tasks'=r[r$Complete,,drop=FALSE],'Deleted tasks'=r[r$Deleted,,drop=FALSE],r)})
  output$history<-renderTable({r<-filtered();r[,c('Task','Job','Status','Original_h','Actual_h','Remaining_h','Error_h','People','Completed'),drop=FALSE]},digits=2,striped=TRUE,na='Unverified')
  output$csv<-downloadHandler(filename='task-history.csv',content=function(file)write.csv(filtered(),file,row.names=FALSE,na='',fileEncoding='UTF-8'))
  observe({s<-state();l<-all_records(s,'logs');t<-all_records(s,'tasks');choices<-if(nrow(l))setNames(l$id,paste(l$date,t$title[match(l$task_id,t$id)],paste0(round(l$hours,2),' h')))else character();updateSelectInput(session,'log_id',choices=choices,selected=isolate(input$log_id))})
  observeEvent(input$log_id,{l<-all_records(state(),'logs');r<-l[match(input$log_id,l$id),];req(nrow(r)==1);updateNumericInput(session,'log_hours',value=r$hours);updateDateInput(session,'log_date',value=r$date);updateTextAreaInput(session,'log_note',value=r$note)})
  change_log<-function(remove=FALSE){s<-state();id<-input$log_id;req(id);table<-if(id%in%s$logs$id)'current'else'archive';l<-if(table=='current')s$logs else s$archive$logs;i<-match(id,l$id);req(!is.na(i))
    if(remove)l<-l[-i,,drop=FALSE]else{s<-edit_work_session(s,id,input$log_hours,input$log_date,input$log_note %||% '');l<-if(table=='current')s$logs else s$archive$logs}
    if(table=='current')s$logs<-l else s$archive$logs<-l
    commit_safely(commit,s)
  }
  observeEvent(input$log_save,change_log())
  observeEvent(input$log_delete,{showModal(modalDialog(title='Delete this time entry?',tags$p('This corrects the actual-time record and changes reports. Undo can restore the entry.'),footer=tagList(modalButton('Cancel'),actionButton(session$ns('log_delete_confirm'),'Delete entry',class='btn-danger'))))})
  observeEvent(input$log_delete_confirm,{change_log(TRUE);removeModal()})
  observe({kind<-input$purge_kind %||% 'tasks';d<-state()$archive[[kind]];label<-if(kind%in%c('jobs','opportunities'))'name'else'title';updateSelectInput(session,'purge_id',choices=choices_id(d,label),selected=isolate(input$purge_id))})
  observeEvent(input$purge,{req(input$purge_kind,input$purge_id);session$userData$purge<-list(kind=input$purge_kind,id=input$purge_id);showModal(modalDialog(title='Remove this record from report history?',tags$p('The record and its associated time logs will be removed from the saved file and analytics. A job removal includes all its removed tasks and goals. Undo works only while its session history is available.'),footer=tagList(modalButton('Cancel'),actionButton(session$ns('purge_confirm'),'Remove historical record',class='btn-danger'))))})
  observeEvent(input$purge_confirm,{tryCatch({p<-session$userData$purge;commit(purge_history(state(),p$kind,p$id));removeModal()},error=notify_error)})

})
